lesson.code:
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1rem;
}

function SkillBadge({ skill }: { skill: string }) {
  return <span className="rounded-md border px-2 py-1 text-sm">{skill}</span>
}

type LoadState<T> =
  | { status: "loading" }
  | { status: "ready"; data: T }
  | { status: "error"; message: string }
